package io.knowledgebrain.notification;
import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.flywaydb.core.Flyway;import org.springframework.jdbc.core.JdbcTemplate;import org.apache.kafka.clients.consumer.*;import static org.junit.jupiter.api.Assertions.*;import io.knowledgebrain.contracts.notification.groupreview.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_NOTIFICATION_KAFKA_BOOTSTRAP",matches=".+")
class GroupReviewKafkaIntegrationTest {
 @Test void minimalPreferenceDeliveryReadAndArchiveReachLiteralTopicByteForByte()throws Exception{var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_NOTIFICATION_DATABASE_URL"));ds.setUser("brain_notification");ds.setPassword(System.getenv("BRAIN_TEST_NOTIFICATION_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var store=new GroupReviewStore(ds,Clock.systemUTC());var a=new GroupReviewStore.Access(ReviewFixtures.ids.next(),ReviewFixtures.ids.next(),ReviewFixtures.ids.next(),1);var pref=store.preference(a,0,true,ReviewFixtures.trace);var raw=ReviewFixtures.feedback(a,pref.enabledAfter()+1);assertTrue(store.accept(ReviewSignal.decode(ReviewSignal.TOPICS.getFirst(),raw)));var n=store.list(a,"ACTIVE","ALL",null,20).items().getFirst();store.change(a,n.notificationId(),1,true,false,ReviewFixtures.trace);store.change(a,n.notificationId(),2,null,true,ReviewFixtures.trace);var expected=new HashMap<String,byte[]>();new JdbcTemplate(ds).query("SELECT id,payload FROM outbox_event WHERE aggregateid IN (?,?)",(rs,i)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),a.principalId(),n.notificationId()).forEach(v->expected.put(v.getKey(),v.getValue()));assertEquals(4,expected.size());var props=NotificationConfiguration.kafka(System.getenv("BRAIN_TEST_NOTIFICATION_KAFKA_BOOTSTRAP"),"/notification-kafka-test","notification-validation-group-"+ReviewFixtures.ids.next());props.put("auto.offset.reset","earliest");try(var c=new KafkaConsumer<String,byte[]>(props)){c.subscribe(List.of("notification.group-review.v1"));var found=new HashSet<String>();long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(found.size()<4&&System.nanoTime()<deadline)for(var row:c.poll(Duration.ofSeconds(1))){if(!Set.of(a.principalId().toString(),n.notificationId().toString()).contains(row.key()))continue;var e=GroupReviewEnvelopeV1.parseFrom(row.value());assertArrayEquals(expected.get(e.getEventId()),row.value());assertEquals(a.spaceId().toString(),e.getSpaceId());assertEquals("notification-service",e.getProducer());assertFalse(new String(row.value(),StandardCharsets.UTF_8).contains("PRIVATE OPINION"));for(var h:Map.of("id",e.getEventId(),"trace_id",ReviewFixtures.trace,"schema_group","notification","schema_artifact","group-review-events","schema_version","1").entrySet())assertEquals(h.getValue(),new String(row.headers().lastHeader(h.getKey()).value(),StandardCharsets.UTF_8));found.add(e.getEventId());}assertEquals(expected.keySet(),found);}assertFalse(store.accept(ReviewSignal.decode(ReviewSignal.TOPICS.getFirst(),raw)));assertEquals(3,store.get(a,n.notificationId()).version());}
}
